\title{A Quantitative Fixed-Point Theory for the Exp-Log (EML) Iteration}
\author{Aristotle}
\date{2026-06-26}

\begin{document}
\maketitle

\begin{abstract}
We develop a complete, quantitative fixed-point theory for the single-operator
\emph{exp-log} (EML) map $f(x) = e^{a}\log(bx+c)$, a nonlinear primitive arising
in the EML neural-network framework. Working over the reals, we show that when
the absolute derivative $|f'(x)| = |e^{a}b/(bx+c)|$ is bounded by a ratio
$\rho < 1$ on a closed interval $[l,h]$ that $f$ maps into itself, the operator
is a $\rho$-contraction. From this we obtain: (i) existence of a fixed point as
the limit of the Picard iteration $x_{n+1} = f(x_n)$; (ii) uniqueness of the
fixed point on the interval; (iii) geometric convergence
$|x_n - x^\star| \le \rho^n |x_0 - x^\star|$; and (iv) a pair of \emph{computable}
error certificates---an \emph{a priori} bound
$|x_n - x^\star| \le \frac{\rho^n}{1-\rho}|x_1 - x_0|$ and an \emph{a posteriori}
bound $|x_{n+1} - x^\star| \le \frac{\rho}{1-\rho}|x_{n+1} - x_n|$---culminating
in a verified \emph{stopping criterion}. We also establish a self-contained
existence result for the family $b=1$, $c=2$, $0 < a < \tfrac12$ via the
intermediate value theorem, locating a positive fixed point in $(1,3)$. All
results are machine-checked.
\end{abstract}

\section{Introduction}

Iterative maps---apply a nonlinear function repeatedly to its own output---are
ubiquitous in numerical analysis and machine learning. Their usefulness hinges
on convergence and on knowing when to stop. We answer both, quantitatively, for
the exp-log operator
\[
  f(x) = e^{a}\,\log(bx + c), \qquad a,b,c \in \R,
\]
a building block of the EML neural-network framework. Our central object is the
Picard iteration $x_{n+1} = f(x_n)$, and our central tool is the contraction
principle. The novelty is a fully explicit, specialized, verified package:
closed-form derivative and contraction constants, both flavors of error bound, a
deployable stopping test, and a parameter-region existence theorem.

\section{Definitions}

\begin{definition}[EML operator]
For $a,b,c\in\R$, the EML operator is $\eml(x) := e^{a}\,\log(bx+c)$, with
natural domain $\{x : bx+c>0\}$.
\end{definition}

\begin{definition}[Iteration sequence]
Given a seed $x_0$, define $x_{n+1} := \eml(x_n)$.
\end{definition}

\begin{definition}[Contraction data]
An EML contraction datum is a tuple $(a,b,c,l,h,\rho)$ with $l<h$,
$0\le\rho<1$, $bx+c>0$ on $[l,h]$, invariance $\eml([l,h])\subseteq[l,h]$, and
the derivative bound $\bigl|e^a b/(bx+c)\bigr|\le\rho$ on $[l,h]$.
\end{definition}

\section{The derivative formula}

\begin{theorem}[Derivative]\label{thm:deriv}
If $bx+c>0$, then $f$ is differentiable at $x$ with
$f'(x) = \dfrac{e^{a}\,b}{bx+c}$.
\end{theorem}

\begin{proof}[Proof sketch]
The affine map $x\mapsto bx+c$ has derivative $b$; by the chain rule the
logarithm contributes a factor $1/(bx+c)$; multiplying by the constant $e^a$
gives the result.
\end{proof}

\begin{corollary}[Asymptotic rate]\label{cor:rate}
At a fixed point $x^\star$ with $bx^\star+c>0$, the asymptotic linear rate of
the iteration is $|f'(x^\star)| = e^a b/(bx^\star+c)$.
\end{corollary}

\section{The contraction estimate}

\begin{theorem}[Lipschitz bound]\label{thm:lip}
Let $l<h$, $bx+c>0$ and $\bigl|e^a b/(bx+c)\bigr|\le\rho$ for all $x\in[l,h]$.
Then $|f(x)-f(y)| \le \rho\,|x-y|$ for all $x,y\in[l,h]$.
\end{theorem}

\begin{proof}[Proof sketch]
The interval is convex and $f$ is differentiable there with $|f'|\le\rho$. The
mean value inequality for a bounded derivative on a convex set yields the
estimate.
\end{proof}

\section{Uniqueness of the fixed point}

\begin{theorem}[At most one fixed point]\label{thm:unique}
Under the hypotheses of Theorem~\ref{thm:lip} with $\rho<1$, if
$x_1,x_2\in[l,h]$ both satisfy $f(x_i)=x_i$, then $x_1=x_2$.
\end{theorem}

\begin{proof}[Proof sketch]
$|x_1-x_2|=|f(x_1)-f(x_2)|\le\rho|x_1-x_2|$, so $(1-\rho)|x_1-x_2|\le0$; as
$\rho<1$, $x_1=x_2$.
\end{proof}

\begin{theorem}[Fixed-point equation]\label{thm:fpeq}
Any fixed point satisfies $x^\star = e^a\log(bx^\star+c)$, equivalently
$\log(bx^\star+c)=x^\star/e^a$.
\end{theorem}

\section{Existence via Picard convergence}

Fix a contraction datum and a seed $x_0\in[l,h]$.

\begin{lemma}[Orbit invariance]\label{lem:inv}
$x_n\in[l,h]$ for all $n$.
\end{lemma}

\begin{theorem}[Geometric decay of differences]\label{thm:decay}
$|x_{n+1}-x_n| \le \rho^{n}\,|x_1-x_0|$ for all $n\ge0$.
\end{theorem}

\begin{proof}[Proof sketch]
Induction: $|x_{n+1}-x_n|=|f(x_n)-f(x_{n-1})|\le\rho|x_n-x_{n-1}|$, then the
inductive hypothesis.
\end{proof}

\begin{theorem}[Cauchy property]\label{thm:cauchy}
The sequence $\{x_n\}$ is Cauchy.
\end{theorem}

\begin{proof}[Proof sketch]
The geometric tail $\sum_{k\ge n}\rho^k|x_1-x_0|$ satisfies the standard
geometric Cauchy test with ratio $\rho<1$.
\end{proof}

\begin{theorem}[Convergence to a fixed point]\label{thm:conv}
There exists $x^\star\in[l,h]$ with $x_n\to x^\star$ and $f(x^\star)=x^\star$.
\end{theorem}

\begin{proof}[Proof sketch]
Completeness gives a limit $x^\star$; closedness of $[l,h]$ keeps it inside;
continuity of $f$ at $x^\star$ lets us pass to the limit in $x_{n+1}=f(x_n)$.
With Theorem~\ref{thm:unique}, $x^\star$ is the unique fixed point in $[l,h]$.
\end{proof}

\section{Quantitative error bounds}

These follow a non-circular logic: contraction $\Rightarrow$ existence of
$x^\star$ $\Rightarrow$ distance estimates $\Rightarrow$ computable bounds. Here
$x^\star$ is a given fixed point in $[l,h]$ (unique by
Theorem~\ref{thm:unique}); the bounds use only the one-step contraction.

\begin{theorem}[One-step contraction toward $x^\star$]\label{thm:onestep}
$|x_{n+1}-x^\star| \le \rho\,|x_n-x^\star|$.
\end{theorem}

\begin{theorem}[Geometric decay to $x^\star$]\label{thm:geo}
$|x_n-x^\star| \le \rho^{n}\,|x_0-x^\star|$.
\end{theorem}

\begin{lemma}[Initial-distance control]\label{lem:initdist}
$|x_0-x^\star| \le \dfrac{|x_1-x_0|}{1-\rho}$.
\end{lemma}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:onestep} ($n=0$) and the triangle inequality,
$|x_0-x^\star|\le|x_1-x_0|+\rho|x_0-x^\star|$; rearrange.
\end{proof}

\begin{theorem}[A priori error bound]\label{thm:apriori}
For all $n\ge0$,
\[
  |x_n-x^\star| \le \frac{\rho^{n}}{1-\rho}\,|x_1-x_0|.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Compose Theorem~\ref{thm:geo} with Lemma~\ref{lem:initdist}.
\end{proof}

To reach tolerance $\varepsilon$ it suffices to take
$n \ge \log\!\bigl(\varepsilon(1-\rho)/|x_1-x_0|\bigr)/\log\rho$.

\begin{theorem}[A posteriori error bound]\label{thm:apost}
For all $n\ge0$,
\[
  |x_{n+1}-x^\star| \le \frac{\rho}{1-\rho}\,|x_{n+1}-x_n|.
\]
\end{theorem}

\begin{proof}[Proof sketch]
With $A=|x_{n+1}-x^\star|$, $B=|x_n-x^\star|$, $C=|x_{n+1}-x_n|$:
$A\le\rho B$ and $B\le C+A$, so $A\le\rho(C+A)$, giving
$A\le\frac{\rho}{1-\rho}C$.
\end{proof}

\begin{theorem}[Computable stopping criterion]\label{thm:stop}
Fix $\varepsilon>0$. If $\dfrac{\rho}{1-\rho}\,|x_{n+1}-x_n|\le\varepsilon$, then
$|x_{n+1}-x^\star|\le\varepsilon$.
\end{theorem}

\begin{proof}[Proof sketch]
Chain Theorem~\ref{thm:apost} with the hypothesis.
\end{proof}

\section{A self-contained existence result}

\begin{theorem}[Positive fixed point for $b=1,c=2$]\label{thm:family}
For every $a$ with $0<a<\tfrac12$, the operator $f(x)=e^a\log(x+2)$ has a fixed
point $x^\star\in(1,3)$ with $x^\star>0$.
\end{theorem}

\begin{proof}[Proof sketch]
Let $g(x)=e^a\log(x+2)-x$ on $[1,3]$ (continuous, since $x+2\ge3>0$). Then
$g(1)=e^a\log3-1>0$ (as $\log3>1$, $e^a\ge1$), and
$g(3)=e^a\log5-3<e^{1/2}\log5<1.7\cdot1.7=2.89<3$, so $g(3)<0$. The intermediate
value theorem gives $x^\star\in(1,3)$ with $g(x^\star)=0$, i.e.
$f(x^\star)=x^\star>0$. The bounds $e^{1/2}<1.7$ and $\log5<1.7$ were verified
from high-precision rational bounds on $e$ (the latter from $5^{10}<e^{17}$).
\end{proof}

\begin{remark}[Series behavior near $a=0$]
At $a=0$ the fixed point solves $x^\star=\log(x^\star+2)$, with
$x^\star\approx1.1462$. Implicit differentiation predicts
$x^\star(a)\approx x^\star(0)+a\,x^\star(0)/\bigl(1-1/(x^\star(0)+2)\bigr)$ with
residual $O(a^2)$.
\end{remark}

\section{Algorithm: certified Picard iteration}

\begin{verbatim}
x_prev := x_0
x_cur  := f(x_prev)
while (rho / (1 - rho)) * |x_cur - x_prev| > eps:
    x_prev := x_cur
    x_cur  := e^a * log(b * x_cur + c)
return x_cur          # certified: |x_cur - x*| <= eps
\end{verbatim}

Each step costs $O(1)$ work; the loop terminates in
$O(\log(1/\varepsilon)/\log(1/\rho))$ steps (Theorem~\ref{thm:apriori}), and the
returned value is certified by Theorem~\ref{thm:stop}.

\section{Discussion and future work}

The theory is complete for the single operator. Five directions extend it:
(1) an order-of-convergence dichotomy (linear with rate $|f'(x^\star)|$ unless
$b=0$); (2) sharpness of the constant $\rho/(1-\rho)$; (3) construction of an
invariant interval from parameters alone (e.g. $b>0$, $c>1$, $e^ab<c\log c$);
(4) monotone two-sided enclosure when $b>0$; and (5) depth-$n$ EML compositions,
where a product $\prod_i\rho_i$ replaces $\rho$ throughout.

\section{Conclusion}

For $f(x)=e^a\log(bx+c)$ we established a closed-form derivative, a contraction
estimate, existence and uniqueness of the fixed point, geometric convergence,
computable a priori and a posteriori error bounds, a deployable stopping
criterion, and a self-contained existence theorem for an explicit parameter
family---elevating the EML iteration to a certified numerical primitive.

\end{document}

